#ifdef GL_ES
precision mediump float;
#endif


// Function to create a color palette inspired by gold and fire
vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 0.5, 0.0);
    vec3 d = vec3(0.00, 0.10, 0.20);
    return a + b * cos(6.28318 * (c * t + d));
}

// 2D Random Noise Function
float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

// 2D Noise Function
float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    // Four corners in 2D
    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    // Cubic Hermine Curve (Smoothstep)
    vec2 u = smoothstep(0.0, 1.0, f);

    // Mix results
    return mix(a, b, u.x) +
           (c - a)* u.y * (1.0 - u.x) +
           (d - b)* u.x * u.y;
}

// Rotate Function
mat2 rotate2D(float angle){
    return mat2(cos(angle), -sin(angle),
                sin(angle),  cos(angle));
}

void mainImage(out vec4 FragColor, in vec2 FragCoord) {
    vec2 uv = FragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0; // Normalize coordinates to range [-1, 1]
    uv.x *= iResolution.x / iResolution.y;

    // Time parameters
    float t = iTime * 0.1;
    float angle = t * 0.5;

    // Rotate UV coordinates
    uv *= rotate2D(angle);

    // Create a moving pattern with noise
    float n = noise(uv * 3.0 + t);

    // Add layers of noise
    n += 0.5 * noise(uv * 10.0 - t * 0.5);
    n += 0.25 * noise(uv * 20.0 + t * 0.2);
    n += 0.125 * noise(uv * 40.0 - t * 0.1);

    // Modulate with sine to create pulsing effect
    float pulse = sin(t * 5.0 + length(uv) * 10.0);

    // Combine noise and pulse
    float brightness = n * pulse;

    // Get color from palette
    vec3 color = palette(brightness);

    // Apply vignette effect
    float vignette = smoothstep(1.0, 0.7, length(uv));
    color *= vignette;

    FragColor = vec4(color, 1.0);
}
